 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        q.append(p)
            if len(cells) != 4:
                continue
            minr, maxr = min(y for y,x in cells), max(y for y,x in cells)
            minc, maxc = min(x for y,x in cells), max(x for y,x in cells)
            if maxr-minr == 1 and maxc-minc == 2:
                if all((minr, x) in cells for x in range(minc, maxc+1)):
                    down += 1
                elif all((maxr, x) in cells for x in range(minc, maxc+1)):
                    up += 1
    out = [[0]*6 for _ in range(3)]
    corners = [(0,0),(2,0),(0,2),(2,2)]
    for n, color, offset in ((up,3,0),(down,1,3)):
        for r,c in corners[:min(n,4)]:
            out[r][offset+c] = color
    return out
